$\begin{aligned} & \frac{\mathrm{W}^{\prime}}{\mathrm{W}}=\frac{\mathrm{V}^{\frac{2}{3}}}{\mathrm{~V}^{\frac{2}{3}}} \\ & \frac{\mathrm{~W}^{\prime}}{\mathrm{W}}=\frac{(2 \mathrm{~V})^{\frac{2}{3}}}{\mathrm{~V}^{\frac{2}{3}}} \\ \therefore \quad \frac{\mathrm{~W}^{\prime}}{\mathrm{W}} & =2^{\frac{2}{3}}=4^{\frac{1}{3}} \\ \therefore \quad \mathrm{~W}^{\prime} & =4^{\frac{1}{3}} \mathrm{~W}\end{aligned}\ldots(\because \mathrm{V}=2 \mathrm{~V})
